def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def best_by(items, key_fn, default=None):
        best_item = default
        best_key = None
        for item in items or []:
            try:
                k = key_fn(item)
            except Exception:
                continue
            if best_key is None or k < best_key:
                best_key = k
                best_item = item
        return best_item

    env = observation.get("environment_name", "")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = best_by(corners, lambda c: -manhattan(c, opp_pos), corners[0])
        move = step_toward(self_pos, target)
        if move == [0, 0]:
            return step_away(self_pos, opp_pos)
        return move

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        if targets:
            # Prefer closest target, but break ties by moving toward center of available targets.
            center = (sx, sy)
            n = 0
            tx = ty = 0
            for t in targets:
                p = pos(t, None)
                if p is None:
                    continue
                tx += p[0]
                ty += p[1]
                n += 1
            if n:
                center = (tx // n, ty // n)
            target = best_by(targets, lambda t: (manhattan(self_pos, pos(t, self_pos)), manhattan(pos(t, self_pos), center)))
            if target is not None:
                tp = pos(target, self_pos)
                return step_toward(self_pos, tp)
        # Fallback: press toward opponent territory / opponent if nothing else.
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        # Denial-aware: prefer resource nearest to self, but if opponent is closer, contest it.
        best = None
        best_score = None
        for r in resources:
            rp = pos(r, None)
            if rp is None:
                continue
            ds = manhattan(self_pos, rp)
            do = manhattan(opp_pos, rp)
            score = (ds - do, ds)
            if best_score is None or score < best_score:
                best_score = score
                best = rp
        if best is not None:
            return step_toward(self_pos, best)

    # Generic fallback: move toward opponent when chasing is useful, otherwise stay safe.
    hazards = observation.get("hazards") or observation.get("walls") or []
    if hazards:
        # If adjacent to many hazards, avoid the opponent-directed move when possible.
        candidate = step_toward(self_pos, opp_pos)
        if candidate != [0, 0]:
            nx, ny = sx + candidate[0], sy + candidate[1]
            for hz in hazards:
                hp = pos(hz, None)
                if hp is not None and hp[0] == nx and hp[1] == ny:
                    return step_away(self_pos, opp_pos)
        return candidate

    return step_toward(self_pos, opp_pos)

